var a=`1422-te-ika-mata`;var n=`world-1422`;var t=`KI`;var o=`oceania`;var c=4;var l=36;var s={en:`Te Ika Mata`,ua:`Те іка мата`};var m={en:`Kiribati-style lime-and-coconut fish salad. This home version uses fully cooked fish instead of the traditional raw marination.`,ua:`Рибний салат по-кірибатійськи з лаймом та кокосом. Домашня версія використовує повністю приготовлену рибу замість традиційного маринування сирої.`};var r=[{en:`Poach fish in gently simmering water until it reaches 63°C in the thickest part, then chill promptly in a covered shallow dish.`,ua:`Припустіть рибу в ледь киплячій воді до температури 63°C у найтовщій частині, після чого швидко охолодіть у накритому неглибокому посуді.`,t:[`poaching`],m:12,i:[[`mahi-mahi`,550,`g`],[`water`,700,`ml`]]},{en:`Dice the cooled cooked fish and combine with lime juice; refrigerate 10 minutes.`,ua:`Наріжте охолоджену готову рибу кубиками й змішайте з соком лайма; поставте в холодильник на 10 хвилин.`,t:[`dicing`,`acid-marination`],m:10,i:[[`lime-juice`,90,`ml`]]},{en:`Finely slice onion and chop tomato and cucumber. Fold gently into the fish.`,ua:`Тонко наріжте цибулю, помідор і огірок. Обережно змішайте з рибою.`,t:[`slicing`,`mixing`],m:8,i:[[`red-onion`,70,`g`],[`tomato`,150,`g`],[`cucumber`,120,`g`]]},{en:`Fold in coconut cream and salt. Keep refrigerated and serve chilled.`,ua:`Додайте кокосові вершки й сіль. Тримайте в холодильнику та подавайте охолодженим.`,t:[`folding-in`],m:6,i:[[`coconut-cream`,230,`ml`],[`sea-salt`,4,`g`]]}];var d={slug:a,id:n,country:`KI`,region:o,servings:4,minutes:36,title:s,text:m,steps:r};export{t as country,d as default,n as id,l as minutes,o as region,c as servings,a as slug,r as steps,m as text,s as title};